              "Unsorted [8, 3, 5, 1]",
              "Split; awaiting sorted runs",
              "Awaiting sorted runs",
              "Awaiting Right run",
              "Both sorted runs ready",
              "Output [—, —, —, —]",
              "Sorted prefix [1, —, —, —]",
              "Sorted prefix [1, 3, —, —]",
              "Sorted prefix [1, 3, 5, —]",
              "Sorted [1, 3, 5, 8]"
            ]
          },
          {
            "id": "left",
            "label": "Left run",
