              }
            ]
          },
          {
            "id": "singletons",
            "label": "Base cases",
            "short": "Reach the singletons",
            "sentence": "Left A, Left B, Right A, and Right B are singleton runs, each already sorted.",
            "why": "Recursion stops at singletons because their internal order cannot be wrong.",
            "active": ["left-a", "left-b", "right-a", "right-b"],
            "calloutRegion": "left-a",
            "readouts": [
              {
                "id": "comparisons",
                "label": "Comparisons: Left run + Right run + Main array",
