                "value": "Cmax(n) = n log₂(n) − n + 1"
              }
            ]
          },
          {
            "id": "left-sorted",
            "label": "Merge left",
            "short": "Build sorted Left run",
            "sentence": "Compare Left A with Left B, emit the smaller item, then append the remainder into Left run.",
            "why": "A singleton merge establishes the same sorted-output rule used by larger merges.",
            "active": ["left"],
            "calloutRegion": "left",
            "readouts": [
              {
                "id": "comparisons",
                "label": "Comparisons: Left run + Right run + Main array",
                "value": "1 + 0 + 0 = 1"
              },
              {
                "id": "invariant",
                "label": "Merge invariant",
                "value": "Left run is sorted."
              },
              {
                "id": "ceiling",
